// emissor.mjs — a rádio: não conhece os ouvintes, só a lista deles.
export function criarEmissor() {
  const inscritos = []; // os ouvintes sintonizados

  return {
    subscribe(callback) {
      if (typeof callback !== 'function') {
        throw new Error('subscriber precisa ser uma função');
      }
      inscritos.push(callback);
      return () => { // devolve a função "desligar o rádio"
        const posicao = inscritos.indexOf(callback);
        if (posicao !== -1) inscritos.splice(posicao, 1);
      };
    },

    emit(evento) {
      for (const inscrito of inscritos) {
        inscrito(evento); // todos recebem o MESMO evento, na ordem da inscrição
      }
      return inscritos.length; // quantos foram avisados
    },
  };
}

// Uso:
const emissor = criarEmissor();
const descadastrar = emissor.subscribe((evento) => console.log('chegou:', evento));
emissor.emit('pedido-criado'); // imprime: chegou: pedido-criado
descadastrar();                // desligou o rádio
emissor.emit('pedido-criado'); // ninguém ouve: emit devolve 0

// notificacoes.mjs — a versão Node: mesma ideia, com a API do EventEmitter.
import { EventEmitter } from 'node:events';

export const notificacoes = new EventEmitter();

// Quem reage, se inscreve com .on('nome-do-evento', callback):
notificacoes.on('pedido-criado', (pedido) => {
  console.log(`E-mail: pedido ${pedido.id} confirmado`);
});

// Quem produz, transmite com .emit('nome-do-evento', dado):
notificacoes.emit('pedido-criado', { id: 1 });
// imprime: E-mail: pedido 1 confirmado

// Passo 1: a rádio — o canal que liga o service aos interessados.
const emissor = criarEmissor();

// Passo 2: dois ouvintes anônimos, cada um com a sua função.
const descadastrarEmail = emissor.subscribe((pedido) => {
  console.log(`E-mail: pedido ${pedido.id} confirmado`);
});
emissor.subscribe((pedido) => {
  console.log(`Relatório: ${pedido.produto} adicionado`);
});

// Passo 3: o service ganha o emissor e transmite DEPOIS de salvar.
function criarServiceComEventos(repositorio, emissor) {
  return {
    registrarPedido(dados) {
      const pedido = repositorio.salvar({ id: 1, ...dados });
      emissor.emit('pedido-criado', pedido); // avisa, sem conhecer os ouvintes
      return pedido;
    },
  };
}

// Passo 4: registrar dispara os dois inscritos, na ordem da inscrição.
const service = criarServiceComEventos(criarRepositorio(), emissor);
service.registrarPedido({ produto: 'Café' });
// imprime: E-mail: pedido 1 confirmado
// imprime: Relatório: Café adicionado

// Passo 5: quem saiu não ouve mais — e o service segue idêntico.
descadastrarEmail();
service.registrarPedido({ produto: 'Bolo' });
// imprime apenas: Relatório: Bolo adicionado
